"""Copilot v2's documentation-search tool: local retrieval core + registration."""

import functools
from typing import List, Optional

import structlog
from pydantic import BaseModel, Field
from pydantic_ai import Agent, RunContext

from rasa.builder import config
from rasa.builder.copilot.constants import TOOL_SEARCH_RASA_DOCUMENTATION
from rasa.builder.copilot.pydantic_ai.prompt_loader import project_uses_mantle_layout
from rasa.builder.copilot.pydantic_ai.run_context import CopilotRunContext
from rasa.builder.document_retrieval.base import BaseRetriever, RetrievalStatus
from rasa.builder.document_retrieval.local.config import (
    EmbedConfig,
    LocalRetrievalConfig,
)
from rasa.builder.document_retrieval.local.embedding import Embedder, build_embedder
from rasa.builder.document_retrieval.local.retrieval import (
    LocalDocumentRetrieval,
)
from rasa.builder.document_retrieval.mintlify import MANTLE_DOCS_SITE, RASA_DOCS_SITE
from rasa.builder.telemetry.langfuse_integration.langfuse_compat import observe

structlogger = structlog.get_logger()


class DocumentSearchDocument(BaseModel):
    """A single retrieved documentation passage with provenance."""

    index: int
    title: str
    url: str
    content: str


class DocumentSearchToolResponse(BaseModel):
    """Structured response for the ``search_rasa_documentation`` tool."""

    documents: List[DocumentSearchDocument] = Field(default_factory=list)
    error: Optional[str] = None


# Read-only, built once and reused for the whole service session: one retriever
# per corpus, since a process serves both v1 and Mantle projects, and one query
# embedder they share (each would otherwise load its own ~130 MB copy of the
# model). Both retrievers are warmed at server startup (warm_retrievers, called
# from main.py), so no request has to build an index; the cached getters still
# build on first use for runs without the Sanic server. They all run on the
# event-loop thread with no await inside, so the caches need no lock.


def _local_config() -> LocalRetrievalConfig:
    """Return the config every serving retriever uses; only the corpus differs."""
    return LocalRetrievalConfig(
        index_cache_dir=config.LOCAL_INDEX_CACHE_DIR,
        embedder=EmbedConfig(embed_cache_dir=config.LOCAL_EMBED_CACHE_DIR),
    )


@functools.cache
def _get_embedder() -> Embedder:
    """Return the query embedder shared by all corpora, building it on first use."""
    return build_embedder(_local_config().embedder)


def _build_retriever(
    artifact_path: Optional[str], setting: str, corpus: str
) -> BaseRetriever:
    """Construct a retriever for ``corpus`` by ingesting its prebuilt parquet vectors.

    Pull-and-serve: the vectors are built off the serving path (CI) and ingested
    directly here, with no corpus load and no embedding at deploy time. All
    corpora share one embedder, built from the same config they search with.

    Args:
        artifact_path: Path to the corpus's parquet vector artifact.
        setting: Name of the builder setting holding ``artifact_path``, for the
            error message.
        corpus: Name of the corpus; each corpus is cached in its own folder.

    Raises:
        ValueError: If ``artifact_path`` is not set.
    """
    if not artifact_path:
        raise ValueError(
            f"Document retrieval for {corpus} requires {setting} (a prebuilt "
            "parquet vector artifact) to be set."
        )
    return LocalDocumentRetrieval.from_artifact(
        _local_config(), artifact_path, corpus=corpus, embedder=_get_embedder()
    )


@functools.cache
def _get_retriever() -> BaseRetriever:
    """Return the CALM v1 retriever, building it on first use.

    A failed build raises and isn't cached, so the next call tries again.
    """
    retriever = _build_retriever(
        config.LOCAL_VECTORS_PARQUET_PATH,
        "LOCAL_VECTORS_PARQUET_PATH",
        RASA_DOCS_SITE.source,
    )
    structlogger.info(
        "copilot_v2.document_search.retriever_initialized",
        backend=type(retriever).__name__,
    )
    return retriever


@functools.cache
def _get_mantle_retriever() -> Optional[BaseRetriever]:
    """Return the Mantle retriever, or None if it can't be built.

    Never raises: a missing or unbuildable Mantle artifact is logged, and the
    caller falls back to the v1 retriever rather than failing the search. The
    outcome, ``None`` included, is cached: the artifact path is process-wide
    config, not something that fixes itself mid-session.
    """
    artifact_path = config.LOCAL_MANTLE_VECTORS_PARQUET_PATH
    if not artifact_path:
        structlogger.warning(
            "copilot_v2.document_search.mantle_artifact_not_configured",
            event_info=(
                "LOCAL_MANTLE_VECTORS_PARQUET_PATH is not set and no bundled "
                "Mantle docs index was found; Mantle projects will fall back to "
                "the CALM v1 documentation corpus."
            ),
        )
        return None

    try:
        retriever = _build_retriever(
            artifact_path,
            "LOCAL_MANTLE_VECTORS_PARQUET_PATH",
            MANTLE_DOCS_SITE.source,
        )
    except Exception as e:
        structlogger.warning(
            "copilot_v2.document_search.mantle_retriever_init_failed",
            event_info="Falling back to the CALM v1 documentation corpus.",
            error=str(e),
        )
        return None

    structlogger.info(
        "copilot_v2.document_search.mantle_retriever_initialized",
        backend=type(retriever).__name__,
    )
    return retriever


def warm_retrievers() -> None:
    """Build every serving retriever now, so no request has to.

    Called once at server startup. Builds the Mantle retriever first; its build
    never raises: a missing or broken artifact is logged, and Mantle projects
    fall back to the CALM v1 corpus. Then builds the CALM v1 retriever, and
    raises whatever its build raises.
    """
    _get_mantle_retriever()
    _get_retriever()


def get_retriever_for_project(project_path: Optional[str]) -> BaseRetriever:
    """Return the retriever for the run's project, dispatching on engine.

    Mantle projects search the Mantle docs corpus when its artifact is
    available; everything else (CALM v1 projects, no project, or a Mantle
    artifact that failed to load) uses the CALM v1 retriever. The layout check
    is the one the system prompt is chosen by, so prompt and corpus agree.
    """
    if project_uses_mantle_layout(project_path):
        mantle_retriever = _get_mantle_retriever()
        if mantle_retriever is not None:
            return mantle_retriever
    return _get_retriever()


async def search_documentation(
    query: str, project_path: Optional[str] = None
) -> DocumentSearchToolResponse:
    """Search Rasa documentation for relevant information.

    Args:
        query: The search query to find relevant documentation.
        project_path: The run's project directory, used to pick the Mantle vs.
            CALM v1 documentation corpus. ``None`` (e.g. no project yet)
            resolves to the CALM v1 corpus.

    Returns:
        DocumentSearchToolResponse with structured results (index, title, url,
        content). Returns an empty list with ``error`` set on failure; never
        raises.
    """
    try:
        response = await get_retriever_for_project(project_path).retrieve(query)

        if response.status is RetrievalStatus.ERROR:
            # The retriever has already logged the failure.
            return DocumentSearchToolResponse(
                error=f"Failed to search documentation: {response.error}"
            )

        documents: List[DocumentSearchDocument] = []
        for idx, result in enumerate(response.results, start=1):
            if not result.url:
                structlogger.warning(
                    "copilot_v2.document_search.missing_url",
                    event_info="Retrieved result has no URL; skipping",
                )
                continue
            documents.append(
                DocumentSearchDocument(
                    index=idx,
                    title=result.title or "Untitled",
                    url=result.url,
                    content=result.content,
                )
            )

        return DocumentSearchToolResponse(documents=documents)

    except Exception as e:
        structlogger.error(
            "copilot_v2.document_search.error",
            event_info="Doc-search tool failed to search documentation",
            error=str(e),
        )
        return DocumentSearchToolResponse(
            error=f"Failed to search documentation: {e!s}"
        )


def register_document_search_tools(agent: Agent[CopilotRunContext, str]) -> None:
    """Register a native Rasa documentation search tool on the agent.

    Registered natively (not via the MCP toolset) so the retrieval call stays
    in-process, uses the warmed local backend, and nests under the run's
    Langfuse trace like other v2 tool calls.
    """

    @agent.tool(
        name=TOOL_SEARCH_RASA_DOCUMENTATION,
        description=(
            "Search the official Rasa documentation for authoritative "
            "information. Use this tool for ALL Rasa-related questions to "
            "ground your answers in truth. Returns relevant documentation "
            "about Rasa concepts, APIs, best practices, configuration, and "
            "troubleshooting with valid links to official docs."
        ),
    )
    @observe(
        name=f"document_search_tool.{TOOL_SEARCH_RASA_DOCUMENTATION}",
        as_type="retriever",
    )
    async def search_rasa_documentation(
        ctx: RunContext[CopilotRunContext],
        query: str,
    ) -> DocumentSearchToolResponse:
        """Search official Rasa documentation for authoritative information."""
        return await search_documentation(query, ctx.deps.project_path)
